$ErrorActionPreference='Stop'
$projectRoot=Split-Path $PSScriptRoot -Parent
$screenPath=Join-Path $projectRoot 'src\screens\DownloadsScreen.tsx'
$text=[IO.File]::ReadAllText($screenPath)
if(-not $text.Contains("from 'react-native-svg'")){$text=$text.Replace("import {SafeAreaView} from 'react-native-safe-area-context';","import {SafeAreaView} from 'react-native-safe-area-context';`nimport Svg,{Circle,Path} from 'react-native-svg';")}
$anchor='export function DownloadsScreen'
$component=@'
function SectionIcon({name}:{name:OfflineSection}){const p={fill:'none',stroke:'#087A45',strokeWidth:1.7,strokeLinecap:'round' as const,strokeLinejoin:'round' as const};if(name==='quran')return <Svg width={29} height={29} viewBox="0 0 32 32"><Path d="M5 8c4.5-1.7 8.2-.7 11 2.2v16c-2.8-2.8-6.5-3.8-11-2.2V8Zm22 0c-4.5-1.7-8.2-.7-11 2.2v16c2.8-2.8 6.5-3.8 11-2.2V8Z" fill="#FFF" {...p}/><Path d="M16 10v16" {...p}/></Svg>;if(name==='hadith')return <Svg width={29} height={29} viewBox="0 0 32 32"><Path d="M9 5.5h14v21H9zM12.5 11h7m-7 5h7m-7 5h5" fill="#FFF" {...p}/><Circle cx="23" cy="8" r="3" fill="#E4B63D"/></Svg>;if(name==='duas')return <Svg width={29} height={29} viewBox="0 0 32 32"><Path d="M16 25S7.5 20.5 7.5 13.8c0-4.6 5.8-6.1 8.5-2.2 2.7-3.9 8.5-2.4 8.5 2.2C24.5 20.5 16 25 16 25Z" fill="#FFF5D2" {...p}/></Svg>;if(name==='books')return <Svg width={29} height={29} viewBox="0 0 32 32"><Path d="m6 20 19-3 2 5-19 3-2-5Zm1-6 18-3 1.5 4-18 3L7 14Zm-1-5 18-3 2 4-18 3-2-4Z" fill="#FFF" {...p}/></Svg>;if(name==='lifestyle')return <Svg width={29} height={29} viewBox="0 0 32 32"><Path d="M7 25C8 14 14 8 25 7c-1 11-7 17-18 18Zm1-1L22 10" fill="#EAF7EE" {...p}/></Svg>;return <Svg width={29} height={29} viewBox="0 0 32 32"><Path d="M9 6h14v20H9zM6 8a2 2 0 0 1 2-2h3v5H8a2 2 0 0 1-2-3Zm20 16a2 2 0 0 1-2 2h-3v-5h3a2 2 0 0 1 2 3Z" fill="#FFF" {...p}/><Path d="m16 11 1.2 2.5 2.8.4-2 2 .5 2.8-2.5-1.3-2.5 1.3.5-2.8-2-2 2.8-.4L16 11Z" fill="#E4B63D"/></Svg>}
'@
if(-not $text.Contains('function SectionIcon(')){$text=$text.Replace($anchor,$component+$anchor)}
$oldIcon='<View style={s.icon}><Text style={s.iconText}>{section.title.slice(0,1)}</Text></View>'
if(-not $text.Contains($oldIcon)){throw 'Section letter icon not found.'};$text=$text.Replace($oldIcon,'<View style={s.icon}><SectionIcon name={section.id}/></View>')
$text=[regex]::Replace($text,'\{record\?<Text style=\{s\.saved\}>.*?</Text>:<Text style=\{s\.notSaved\}>.*?</Text>\}',"{record?<Text style={s.saved}>SAVED - {formatDownloadSize(record.bytes)}</Text>:<Text style={s.notSaved}>NOT DOWNLOADED</Text>}")
$text=[regex]::Replace($text,'<Text style=\{s\.downloadText\}>\{loading\?.*?</Text>',"<Text style={s.downloadText}>{loading?`${progress}%`:record?'Update':'Download'}</Text>")
$text=$text.Replace("card:{width:'48.5%',minHeight:205,padding:13,borderWidth:1,borderColor:'#DDE9E1',borderRadius:17,backgroundColor:'#FFF',alignItems:'flex-start'}","card:{width:'48.5%',minHeight:224,padding:14,borderWidth:1,borderColor:'#D7E7DC',borderRadius:20,backgroundColor:'#FFF',alignItems:'flex-start',shadowColor:'#174832',shadowOffset:{width:0,height:3},shadowOpacity:.06,shadowRadius:8,elevation:2}")
$text=$text.Replace("icon:{width:43,height:43,borderRadius:14,backgroundColor:'#E8F5EC',alignItems:'center',justifyContent:'center'}","icon:{width:48,height:48,borderRadius:16,backgroundColor:'#EAF6EE',borderWidth:1,borderColor:'#D4EADC',alignItems:'center',justifyContent:'center'}")
$text=$text.Replace("cardTitle:{fontSize:15,fontWeight:'800',color:INK}","cardTitle:{fontSize:16,fontWeight:'800',color:INK}")
$text=$text.Replace("cardSub:{marginTop:3,fontSize:10,lineHeight:14,color:'#718078'}","cardSub:{marginTop:5,minHeight:42,fontSize:10,lineHeight:14,color:'#718078'}")
$text=$text.Replace("saved:{marginTop:7,fontSize:9.5,fontWeight:'700',color:G},notSaved:{marginTop:7,fontSize:9.5,color:'#9A7A36'}","saved:{alignSelf:'flex-start',marginTop:8,paddingHorizontal:7,paddingVertical:4,borderRadius:8,backgroundColor:'#E8F6ED',fontSize:8,fontWeight:'800',color:G},notSaved:{alignSelf:'flex-start',marginTop:8,paddingHorizontal:7,paddingVertical:4,borderRadius:8,backgroundColor:'#FFF7E6',fontSize:8,fontWeight:'800',color:'#9A7028'}")
$text=$text.Replace("download:{minWidth:52,height:38,paddingHorizontal:9,borderRadius:12,backgroundColor:G,alignItems:'center',justifyContent:'center'}","download:{flex:1,height:40,paddingHorizontal:8,borderRadius:12,backgroundColor:G,alignItems:'center',justifyContent:'center'}")
$text=$text.Replace("remove:{width:28,height:28,borderRadius:10","remove:{width:40,height:40,borderRadius:12")
[IO.File]::WriteAllText($screenPath,$text)
